Lemma bc_tap : forall (G : bvmap 5 word) (s0 n0 kt : Z) (sp rg bv : Z),
  acc_regs G s0 n0 -> bc_avg kt s0 n0 -> 0 <= kt -> kt + 1 <= 2048 -> FB fmt_single 1 sp -> FB fmt_single 1 rg -> 0 <= bv <= 255 ->
  let SPw := nan_box (bv_extract 0 32 (le_bytes_to_word (le4 (Z_to_bv 64 sp)))) in
  let RGw := nan_box (bv_extract 0 32 (le_bytes_to_word (le4 (Z_to_bv 64 rg)))) in
  let KW := fmul_s RNE SPw RGw in
  exists s1 n1 : Z, fma_s F_MADD RNE KW (fcvt_s_wu RNE (Z_to_bv 64 bv)) (reg_get G (Z_to_bv 5 15)) = nan_box (Z_to_bv 32 s1)
    /\ fadd_s RNE (reg_get G (Z_to_bv 5 14)) KW = nan_box (Z_to_bv 32 n1) /\ bc_avg (kt + 1) s1 n1.
Proof.
