(* [comment removed for export] *)
Ltac guard32 :=
  lazymatch goal with
  | |- context [negb (bv_eqb (Z_to_bv 64 (bv_swrap 32 ?x)) (Z_to_bv 64 ?y))] =>
      sw32; let x' := match goal with |- context [negb (bv_eqb (Z_to_bv 64 (bv_swrap 32 ?x2)) (Z_to_bv 64 y))] => x2 end in
      replace (bv_swrap 32 x') with y by (rewrite (bv_swrap_small 32 x') by (change (bv_half_modulus 32) with 2147483648; lia); lia);
      rewrite bv_eqb_refl; change (negb true) with false; cbv iota
  end.
