(* [comment removed for export] *)
Ltac ltsguard :=
  sw32;
  repeat match goal with |- context [bv_swrap 32 ?x] => sw32s x end;
  lazymatch goal with |- context [bv_lts (Z_to_bv 64 ?a) (Z_to_bv 64 ?b)] =>
    rewrite (lts_lit a b) by lia;
    first [ replace (a <? b) with false by (symmetry; apply Z.ltb_ge; lia)
          | replace (a <? b) with true by (symmetry; apply Z.ltb_lt; lia) ] end;
  cbv iota.
