Ltac freg_rw G H :=
  lazymatch type of H with reg_get G (Z_to_bv 5 ?k) = ?v =>
    repeat (match goal with |- context [reg_get G ?r] =>
      let E := fresh "E" in assert (E : reg_get G r = v) by (apply (reg_lit G r k v); [reflexivity | exact H]);
      rewrite E; clear E end) end.
