Definition hp_k_exit (ra sp gp tp s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t4 t5 t6 : word) (F : bvmap 5 word) (m : mem)
  : machine_state -> Prop :=
  fun ms' => exists (t0' t1' t2' t3' a0' : word) (F' : bvmap 5 word) (fc' : bv 32) (s' n' : Z),
    ms' = MS (mkR ra sp gp tp t0' t1' t2' s0 s1 a0' a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3' t4 t5 t6)
             F' (Z_to_bv 64 0xcf96c) fc' None m (seg_rom asegs)
    /\ fs_agree F F' /\ frm0 fc' /\ acc_regs F' s' n' /\ bc_avg 21 s' n'.
Lemma hp_k_loop : forall (n : nat) (kk : Z) (p : hpp) (ks rs : Z -> Z) (LS J : Z)
    (ra sp gp tp t1 t2 s0 a0 a1 a3 a4 a6 a7 t3 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem) (s n0 : Z),
  Z.of_nat n = 21 - kk -> 0 <= kk -> (1 <= n)%nat -> hp_ok p -> frm0 fc ->
  hp_DS p <= LS -> hp_DS p <= LS + J - 10 -> LS + J + 11 <= hp_DS p + hp_N p -> 11 <= J <= 20011 ->
  wr_at asegs m (hp_DS p) (hp_N p) -> acc asegs m (hp_DS p) (hp_N p) -> hp_kcells p ks rs m -> mem_inv asegs m ->
  rw_cells asegs m (hp_S1 p + 184) [C8 (Z_to_bv 64 1)] ->
  acc_regs F s n0 -> bc_avg kk s n0 ->
  evt asegs (hp_k_exit ra sp gp tp s0 (Z_to_bv 64 (hp_S1 p)) a1 (Z_to_bv 64 LS) a3 a4 (Z_to_bv 64 J) a6 (Z_to_bv 64 J)
               (Z_to_bv 64 (hp_RR p)) (Z_to_bv 64 2147450880) (Z_to_bv 64 (hp_wpl p)) (Z_to_bv 64 3) (Z_to_bv 64 1)
               (Z_to_bv 64 (18446744073709551615 - hp_RR p)) (Z_to_bv 64 1) (Z_to_bv 64 10) (Z_to_bv 64 (hp_c p)) (Z_to_bv 64 (hp_SP p))
               (Z_to_bv 64 11) t5 t6 F m)
    (MS (mkR ra sp gp tp (Z_to_bv 64 (kk - 10)) t1 t2 s0 (Z_to_bv 64 (hp_S1 p)) a0 a1 (Z_to_bv 64 LS) a3 a4 (Z_to_bv 64 J) a6 a7
             (Z_to_bv 64 (hp_RR p)) (Z_to_bv 64 2147450880) (Z_to_bv 64 (hp_wpl p)) (Z_to_bv 64 3) (Z_to_bv 64 1)
             (Z_to_bv 64 (18446744073709551615 - hp_RR p)) (Z_to_bv 64 1) (Z_to_bv 64 10) (Z_to_bv 64 (hp_c p)) (Z_to_bv 64 (hp_SP p))
             t3 (Z_to_bv 64 11) t5 t6)
        F (Z_to_bv 64 0xcf840) fc None m (seg_rom asegs)).
Proof.
