(* [comment removed for export] *)
Definition hp_LS (p : hpp) (i : Z) : Z := hp_DS p + (11 + i) * hp_wpl p * 4.
Definition hp_LT (p : hpp) (i : Z) : Z := hp_DT p + (11 + i) * hp_wpl p * 4.

(* [comment removed for export] *)
Definition hp_j_exit (p : hpp) (i : Z) (ra sp gp tp s0 t5 t6 : word) (F : bvmap 5 word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (t0' t1' t2' t3' a0' a2' a3' a4' a5' a6' a7' : word) (F' : bvmap 5 word) (fc' : bv 32) (m' : mem),
    ms' = MS (mkR ra sp gp tp t0' t1' t2' s0 (Z_to_bv 64 (hp_S1 p)) a0' (Z_to_bv 64 i) a2' a3' a4' a5' a6' a7'
                  (Z_to_bv 64 (hp_RR p)) (Z_to_bv 64 2147450880) (Z_to_bv 64 (hp_wpl p)) (Z_to_bv 64 3) (Z_to_bv 64 1)
                  (Z_to_bv 64 (18446744073709551615 - hp_RR p)) (Z_to_bv 64 1) (Z_to_bv 64 10) (Z_to_bv 64 (hp_c p)) (Z_to_bv 64 (hp_SP p))
                  t3' (Z_to_bv 64 11) t5 t6)
             F' (Z_to_bv 64 0xcfa00) fc' None m' (seg_rom asegs)
    /\ fs_agree F F' /\ frm0 fc' /\ munch [(hp_DT p, hp_DT p + hp_N p)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.
Lemma hp_j_loop : forall (n : nat) (p : hpp) (ks rs : Z -> Z) (i j : Z)
    (ra sp gp tp t0 t1 t2 s0 a0 a5 a6 a7 t3 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem),
  Z.of_nat n = hp_w p - j -> 0 <= j -> (1 <= n)%nat -> 0 <= i < hp_h p -> hp_ok p -> frm0 fc -> hp_fregs F ->
  (forall m', munch [(hp_DT p, hp_DT p + hp_N p)] m m' -> wmono asegs m m' -> hp_ro p ks rs m') ->
  wr_at asegs m (hp_DT p) (hp_N p) -> acc asegs m (hp_DT p) (hp_N p) -> mem_inv asegs m ->
  evt asegs (hp_j_exit p i ra sp gp tp s0 t5 t6 F m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 (Z_to_bv 64 (hp_S1 p)) a0 (Z_to_bv 64 i) (Z_to_bv 64 (hp_LS p i)) (Z_to_bv 64 (hp_LT p i)) (Z_to_bv 64 j) a5 a6 a7
             (Z_to_bv 64 (hp_RR p)) (Z_to_bv 64 2147450880) (Z_to_bv 64 (hp_wpl p)) (Z_to_bv 64 3) (Z_to_bv 64 1)
             (Z_to_bv 64 (18446744073709551615 - hp_RR p)) (Z_to_bv 64 1) (Z_to_bv 64 10) (Z_to_bv 64 (hp_c p)) (Z_to_bv 64 (hp_SP p))
             t3 (Z_to_bv 64 11) t5 t6)
